text(await tools.apply_patch("*** Begin Patch
*** Add File: gyrokinetic/zero/gkyl_gk_geometry_cylindrical.h
+#pragma once
+
+#include <gkyl_gk_geometry.h>
+
+/**
+ * Construct a three-dimensional, first-order cylindrical geometry on a
+ * (r, theta, z) grid. The map to physical space is built in. The magnetic
+ * field callback must return a field parallel to z.
+ *
+ * @param geometry_inp Geometry grid, basis, and magnetic-field input.
+ * @return Cylindrical geometry object.
+ */
+struct gk_geometry *gkyl_gk_geometry_cylindrical_inew(
+  struct gkyl_gk_geometry_inp *geometry_inp
+);
*** Add File: gyrokinetic/zero/gkyl_gk_geometry_cylindrical_priv.h
+#pragma once
+
+#include <gkyl_gk_geometry.h>
+
+void gkyl_gk_geometry_cylindrical_advance_interior(struct gk_geometry *up);
+void gkyl_gk_geometry_cylindrical_advance_surface(struct gk_geometry *up, int dir);
*** Add File: gyrokinetic/zero/gk_geometry_cylindrical.c
+#include <assert.h>
+#include <math.h>
+
+#include <gkyl_array.h>
+#include <gkyl_gk_geometry_cylindrical.h>
+#include <gkyl_gk_geometry_cylindrical_priv.h>
+#include <gkyl_gk_geometry_mapc2p.h>
+#include <gkyl_gk_geometry_priv.h>
+#include <gkyl_nodal_ops.h>
+
+static void
+gk_geometry_cylindrical_mapc2p(double t, const double *xc, double *xp, void *ctx)
+{
+  xp[0] = xc[0] * cos(xc[1]);
+  xp[1] = xc[0] * sin(xc[1]);
+  xp[2] = xc[2];
+}
+
+struct gk_geometry *
+gkyl_gk_geometry_cylindrical_inew(struct gkyl_gk_geometry_inp *geometry_inp)
+{
+  assert(geometry_inp->geo_grid.ndim == 3);
+  assert(geometry_inp->geo_basis.poly_order == 1);
+  assert(geometry_inp->geo_grid.lower[0] >= 0.0);
+  assert(geometry_inp->bfield_func);
+
+  struct gkyl_gk_geometry_inp cyl_inp = *geometry_inp;
+  cyl_inp.geometry_id = GKYL_GEOMETRY_CYLINDRICAL;
+  cyl_inp.mapc2p = gk_geometry_cylindrical_mapc2p;
+  cyl_inp.c2p_ctx = 0;
+  return gkyl_gk_geometry_mapc2p_new(&cyl_inp);
+}
+
+static void
+gk_geometry_cylindrical_project(
+  struct gkyl_nodal_ops *n2m, struct gk_geometry *up, int ncomp, struct gkyl_array *nodal,
+  struct gkyl_array *modal
+)
+{
+  gkyl_nodal_ops_n2m(
+    n2m, &up->basis, &up->grid, &up->nrange_int, &up->local, ncomp, nodal, modal, true
+  );
+}
+
+void
+gkyl_gk_geometry_cylindrical_advance_interior(struct gk_geometry *up)
+{
+  struct gk_geom_int *geo = &up->geo_int;
+  struct gkyl_range_iter iter;
+  gkyl_range_iter_init(&iter, &up->nrange_int);
+  while (gkyl_range_iter_next(&iter)) {
+    long idx = gkyl_range_idx(&up->nrange_int, iter.idx);
+    double r = gk_geometry_node_coord(
+      &up->grid, &up->local, &up->global, &up->nrange_int, 0, iter.idx[0], 2, true
+    );
+    double theta = gk_geometry_node_coord(
+      &up->grid, &up->local, &up->global, &up->nrange_int, 1, iter.idx[1], 2, true
+    );
+    double c = cos(theta), s = sin(theta);
+    double bmag = gkyl_array_cfetch(geo->bmag_nodal, idx)[0];
+    assert(r > 0.0 && bmag > 0.0);
+
+    double *gij_cov = gkyl_array_fetch(geo->g_ij_nodal, idx);
+    gij_cov[0] = 1.0;
+    gij_cov[1] = gij_cov[2] = gij_cov[4] = 0.0;
+    gij_cov[3] = r * r;
+    gij_cov[5] = 1.0;
+
+    double *tangent = gkyl_array_fetch(geo->dxdz_nodal, idx);
+    tangent[0] = c;
+    tangent[1] = s;
+    tangent[2] = 0.0;
+    tangent[3] = -r * s;
+    tangent[4] = r * c;
+    tangent[5] = 0.0;
+    tangent[6] = tangent[7] = 0.0;
+    tangent[8] = 1.0;
+
+    double *dual = gkyl_array_fetch(geo->dzdx_nodal, idx);
+    dual[0] = c;
+    dual[1] = s;
+    dual[2] = 0.0;
+    dual[3] = -s / r;
+    dual[4] = c / r;
+    dual[5] = 0.0;
+    dual[6] = dual[7] = 0.0;
+    dual[8] = 1.0;
+
+    double *dualmag = gkyl_array_fetch(geo->dualmag_nodal, idx);
+    dualmag[0] = 1.0;
+    dualmag[1] = 1.0 / r;
+    dualmag[2] = 1.0;
+    double *normals = gkyl_array_fetch(geo->normals_nodal, idx);
+    normals[0] = c;
+    normals[1] = s;
+    normals[2] = 0.0;
+    normals[3] = -s;
+    normals[4] = c;
+    normals[5] = 0.0;
+    normals[6] = normals[7] = 0.0;
+    normals[8] = 1.0;
+
+    gkyl_array_fetch(geo->jacobgeo_nodal, idx)[0] = r;
+    double *bi = gkyl_array_fetch(geo->b_i_nodal, idx);
+    bi[0] = bi[1] = 0.0;
+    bi[2] = 1.0;
+    double *bcart = gkyl_array_fetch(geo->bcart_nodal, idx);
+    bcart[0] = bcart[1] = 0.0;
+    bcart[2] = 1.0;
+    gkyl_array_fetch(geo->B3_nodal, idx)[0] = bmag;
+    gkyl_array_fetch(geo->rtg33inv_nodal, idx)[0] = 1.0;
+    double *bioverJB = gkyl_array_fetch(geo->bioverJB_nodal, idx);
+    bioverJB[0] = bioverJB[1] = 0.0;
+    bioverJB[2] = 1.0 / (r * bmag);
+  }
+
+  struct gkyl_nodal_ops *n2m = gkyl_nodal_ops_new(&up->basis, &up->grid, false);
+  struct {
+    int ncomp;
+    struct gkyl_array *nodal, *modal;
+  } fields[] = {
+    {6, geo->g_ij_nodal, geo->g_ij},
+    {9, geo->dxdz_nodal, geo->dxdz},
+    {9, geo->dzdx_nodal, geo->dzdx},
+    {3, geo->dualmag_nodal, geo->dualmag},
+    {9, geo->normals_nodal, geo->normals},
+    {1, geo->jacobgeo_nodal, geo->jacobgeo},
+    {3, geo->b_i_nodal, geo->b_i},
+    {3, geo->bcart_nodal, geo->bcart},
+    {1, geo->B3_nodal, geo->B3},
+    {1, geo->rtg33inv_nodal, geo->rtg33inv},
+    {3, geo->bioverJB_nodal, geo->bioverJB},
+  };
+  for (int i = 0; i < sizeof(fields) / sizeof(fields[0]); ++i) {
+    gk_geometry_cylindrical_project(n2m, up, fields[i].ncomp, fields[i].nodal, fields[i].modal);
+  }
+  gkyl_nodal_ops_release(n2m);
+  gkyl_array_copy(geo->g_ij_neut, geo->g_ij);
+
+  // Project inverses directly at positive-radius quadrature points. Inverting
+  // a p1 projection of r*r can give zero or a negative determinant in the
+  // cell touching the axis.
+  struct gkyl_array *nodal = gkyl_array_new(GKYL_DOUBLE, 1, up->nrange_int.volume);
+  struct gkyl_array *gij_nodal = gkyl_array_new(GKYL_DOUBLE, 6, up->nrange_int.volume);
+  gkyl_range_iter_init(&iter, &up->nrange_int);
+  while (gkyl_range_iter_next(&iter)) {
+    long idx = gkyl_range_idx(&up->nrange_int, iter.idx);
+    double r = gkyl_array_cfetch(geo->jacobgeo_nodal, idx)[0];
+    double *gij = gkyl_array_fetch(gij_nodal, idx);
+    gij[0] = 1.0;
+    gij[1] = gij[2] = gij[4] = 0.0;
+    gij[3] = 1.0 / (r * r);
+    gij[5] = 1.0;
+  }
+  n2m = gkyl_nodal_ops_new(&up->basis, &up->grid, false);
+  gk_geometry_cylindrical_project(n2m, up, 6, gij_nodal, geo->gij);
+  gkyl_array_copy(geo->gij_neut, geo->gij);
+
+#define PROJECT_CYL_FIELD(dest, value)                                                   \
+  do {                                                                                    \
+    gkyl_range_iter_init(&iter, &up->nrange_int);                                         \
+    while (gkyl_range_iter_next(&iter)) {                                                 \
+      long idx = gkyl_range_idx(&up->nrange_int, iter.idx);                               \
+      double r = gkyl_array_cfetch(geo->jacobgeo_nodal, idx)[0];                          \
+      double bmag = gkyl_array_cfetch(geo->bmag_nodal, idx)[0];                           \
+      gkyl_array_fetch(nodal, idx)[0] = (value);                                          \
+    }                                                                                     \
+    gk_geometry_cylindrical_project(n2m, up, 1, nodal, (dest));                          \
+  } while (0)
+
+  PROJECT_CYL_FIELD(geo->jacobgeo_inv, 1.0 / r);
+  PROJECT_CYL_FIELD(geo->cmag, r * bmag);
+  PROJECT_CYL_FIELD(geo->jacobtot, r * bmag);
+  PROJECT_CYL_FIELD(geo->jacobtot_inv, 1.0 / (r * bmag));
+  PROJECT_CYL_FIELD(geo->gxxj, r);
+  PROJECT_CYL_FIELD(geo->gxyj, 0.0);
+  PROJECT_CYL_FIELD(geo->gyyj, 1.0 / r);
+  PROJECT_CYL_FIELD(geo->gxzj, 0.0);
+  PROJECT_CYL_FIELD(geo->eps2, 0.0);
+#undef PROJECT_CYL_FIELD
+
+  gkyl_array_clear(geo->dualcurlbhat, 0.0);
+  gkyl_array_clear(geo->dualcurlbhatoverB, 0.0);
+  gkyl_array_clear(geo->curlbhat_nodal, 0.0);
+  gkyl_array_clear(geo->dualcurlbhat_nodal, 0.0);
+  gkyl_array_clear(geo->dualcurlbhatoverB_nodal, 0.0);
+  gkyl_array_release(gij_nodal);
+  gkyl_array_release(nodal);
+  gkyl_nodal_ops_release(n2m);
+}
+
+void
+gkyl_gk_geometry_cylindrical_advance_surface(struct gk_geometry *up, int dir)
+{
+  struct gk_geom_surf *geo = &up->geo_surf[dir];
+  struct gkyl_range_iter iter;
+  gkyl_range_iter_init(&iter, &up->nrange_surf[dir]);
+  while (gkyl_range_iter_next(&iter)) {
+    long idx = gkyl_range_idx(&up->nrange_surf[dir], iter.idx);
+    double r = gk_geometry_node_coord(
+      &up->grid, &up->local, &up->global, &up->nrange_surf[dir], 0, iter.idx[0],
+      dir == 0 ? 1 : 2, dir != 0
+    );
+    double theta = gk_geometry_node_coord(
+      &up->grid, &up->local, &up->global, &up->nrange_surf[dir], 1, iter.idx[1],
+      dir == 1 ? 1 : 2, dir != 1
+    );
+    double c = cos(theta), s = sin(theta);
+    double bmag = gkyl_array_cfetch(geo->bmag_nodal, idx)[0];
+    assert(bmag > 0.0);
+    double *gij = gkyl_array_fetch(geo->g_ij_nodal, idx);
+    gij[0] = gij[5] = 1.0;
+    gij[1] = gij[2] = gij[4] = 0.0;
+    gij[3] = r * r;
+    double *tangent = gkyl_array_fetch(geo->dxdz_nodal, idx);
+    tangent[0] = c;
+    tangent[1] = s;
+    tangent[2] = 0.0;
+    tangent[3] = -r * s;
+    tangent[4] = r * c;
+    tangent[5] = 0.0;
+    tangent[6] = tangent[7] = 0.0;
+    tangent[8] = 1.0;
+    double *dual = gkyl_array_fetch(geo->dzdx_nodal, idx);
+    dual[0] = c;
+    dual[1] = s;
+    dual[2] = 0.0;
+    dual[3] = r > 0.0 ? -s / r : 0.0;
+    dual[4] = r > 0.0 ? c / r : 0.0;
+    dual[5] = 0.0;
+    dual[6] = dual[7] = 0.0;
+    dual[8] = 1.0;
+    double *dualmag = gkyl_array_fetch(geo->dualmag_nodal, idx);
+    dualmag[0] = dualmag[2] = 1.0;
+    dualmag[1] = r > 0.0 ? 1.0 / r : 0.0;
+    double *normals = gkyl_array_fetch(geo->normals_nodal, idx);
+    normals[0] = c;
+    normals[1] = s;
+    normals[2] = 0.0;
+    normals[3] = -s;
+    normals[4] = c;
+    normals[5] = 0.0;
+    normals[6] = normals[7] = 0.0;
+    normals[8] = 1.0;
