+static void
+check_flux_updater(enum gkyl_gk_collisionless_type type, bool use_gpu)
+{
+  for (int axis = 0; axis < 2; ++axis) {
+    struct flux_result mixed = run_flux_updater(type, axis, true, use_gpu);
+    // The annulus allows a normal-flux reference at every face. At the axis,
+    // use the CPU zero-flux result as the reference (also checks CUDA parity).
+    struct flux_result ref = run_flux_updater(type, axis, axis, false);
+    struct gkyl_range_iter iter;
+    gkyl_range_iter_init(&iter, &mixed.ext);
+    int nzero = 0, nnonzero = 0;
+    while (gkyl_range_iter_next(&iter)) {
+      long loc = gkyl_range_idx(&mixed.ext, iter.idx);
+      const double *actual = gkyl_array_cfetch(mixed.flux, loc);
+      const double *expected = gkyl_array_cfetch(ref.flux, loc);
+      for (int k = 0; k < 88; ++k) {
+        int dir = k/24;
+        bool zero = false;
+        if (dir < 3) {
+          int face = dir == 1 ? mixed.local.upper[dir]+1 : mixed.local.lower[dir];
+          zero = iter.idx[dir] == face;
