+        }
+        TEST_CHECK(finite_bits(actual[k]));
+        if (zero) {
+          TEST_CHECK(actual[k] == 0.0);
+          ++nzero;
+        } else {
+          TEST_CHECK(gkyl_compare(actual[k], expected[k], 1e-12));
+          if (actual[k] != -777.0 && fabs(actual[k]) > 1e-12) ++nnonzero;
+        }
+      }
+      const double *cfl = gkyl_array_cfetch(mixed.cfl, loc);
+      TEST_CHECK(finite_bits(cfl[0]));
+      TEST_CHECK(cfl[0] >= 0.0);
+      if (axis) {
+        const double *cfl_ref = gkyl_array_cfetch(ref.cfl, loc);
+        TEST_CHECK(gkyl_compare(cfl[0], cfl_ref[0], 1e-12));
+      }
+    }
+    TEST_CHECK(nzero > 0);
+    TEST_CHECK(nnonzero > 0);
+    release_flux_result(mixed);
+    release_flux_result(ref);
+  }
+}
